fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let l = s.len();
    let p = l - (l % 3); // largest multiple of 3 <= l

    // Start with an identity copy; we'll overwrite the transformed prefix.
    let mut res = s.clone();

    // Apply the mapping on each full triplet.
    // For triplet starting at j: (j, j+1, j+2) -> (s[j+2], s[j], s[j+1])
    for j in (0..p).step_by(3) {
        res[j] = s[j + 2];     // i % 3 == 0
        res[j + 1] = s[j];     // i % 3 == 1 (i-1 == j)
        res[j + 2] = s[j + 1]; // implied remaining position
    }

    res
}

